mapper.select:
SELECT id, recipient_id, sender_id, action_type, target_id, 
       content_snapshot, is_read, create_time
FROM notification
WHERE recipient_id = #{recipientId}
ORDER BY create_time DESC
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE notification
SET is_read = true
WHERE recipient_id = #{recipientId}
  AND is_read = false
  AND create_time <= #{beforeTime}
